{
  "action": "collect_information",
  "message": "I can review your canceled business flight and, once confirmed, issue a travel certificate as a goodwill gesture. To proceed, please share the details below.",
  "required_information": [
    "Your user_id",
    "Reservation_id for the canceled flight (if known). If not known, please provide the flight number and flight date, plus origin and destination.",
    "Number of passengers on that reservation"
  ],
  "notes": "Once I confirm the flight was canceled by the airline and the reservation details, I can issue a travel certificate based on the number of passengers on the reservation."
}

